"""C++ contracts for the semantically distinct priority-queue v2 family."""
from __future__ import annotations

from dataclasses import dataclass, replace


@dataclass(frozen=True)
class Case:
    task_id: str
    class_name: str
    mechanism: str
    contract: str
    header: str
    reference: str
    starter: str
    visible: str
    hidden: str
    required_tokens: tuple[str, ...]


INCLUDES = """#include <array>
#include <cstddef>
#include <cstdint>
#include <deque>
#include <limits>
#include <memory>
#include <optional>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>
#include <vector>
"""


def _header(body: str) -> str:
    return f"#pragma once\n{INCLUDES}\nnamespace curriculum {{\n{body}\n}}  // namespace curriculum\n"


def _source(body: str, mechanism: str) -> str:
    return f'#include "task.h"\n#include <algorithm>\n#include <stdexcept>\n// mechanism:{mechanism}\nnamespace curriculum {{\n{body}\n}}  // namespace curriculum\n'


def _test(body: str) -> str:
    return f'''#include "task.h"
#include <string>
#include <vector>
int main() {{ using namespace curriculum; int failures = 0; const auto check = [&](bool ok) {{ if (!ok) ++failures; }}; {body} return failures == 0 ? 0 : 1; }}
'''


def _emergency() -> Case:
    h = _header('''class EmergencyDispatch {
public:
  struct Incident { int id; int severity; int deadline; };
  bool report(int id, int severity, int deadline);
  bool revise(int id, int severity, int deadline);
  bool cancel(int id);
  std::optional<Incident> dispatch_next();
  bool debug_valid_heap() const;
  std::size_t pending() const { return heap_.size(); }
private:
  struct Node { Incident value; std::size_t sequence; };
  std::vector<Node> heap_; std::unordered_map<int, std::size_t> index_; std::size_t sequence_ = 0;
  static bool better(const Node&, const Node&); void swap_nodes(std::size_t, std::size_t); void sift_up(std::size_t); void sift_down(std::size_t);
};''')
    r = _source('''bool EmergencyDispatch::better(const Node& a, const Node& b) { return a.value.severity != b.value.severity ? a.value.severity > b.value.severity : a.value.deadline != b.value.deadline ? a.value.deadline < b.value.deadline : a.sequence < b.sequence; }
void EmergencyDispatch::swap_nodes(std::size_t a, std::size_t b) { std::swap(heap_[a], heap_[b]); index_[heap_[a].value.id] = a; index_[heap_[b].value.id] = b; }
void EmergencyDispatch::sift_up(std::size_t i) { while (i) { const auto p = (i - 1U) / 2U; if (!better(heap_[i], heap_[p])) break; swap_nodes(i, p); i = p; } }
void EmergencyDispatch::sift_down(std::size_t i) { for (;;) { auto best = i; const auto l = 2U*i+1U, r = l+1U; if (l < heap_.size() && better(heap_[l], heap_[best])) best=l; if (r < heap_.size() && better(heap_[r], heap_[best])) best=r; if (best==i) break; swap_nodes(i,best); i=best; } }
bool EmergencyDispatch::report(int id,int severity,int deadline) { if(id<=0||severity<0||deadline<0||index_.count(id)) return false; heap_.push_back({{id,severity,deadline},sequence_++}); index_[id]=heap_.size()-1U; sift_up(heap_.size()-1U); return true; }
bool EmergencyDispatch::revise(int id,int severity,int deadline) { const auto found=index_.find(id); if(found==index_.end()||severity<0||deadline<0) return false; const auto i=found->second; heap_[i].value.severity=severity; heap_[i].value.deadline=deadline; sift_up(i); sift_down(index_[id]); return true; }
bool EmergencyDispatch::cancel(int id) { const auto found=index_.find(id); if(found==index_.end()) return false; const auto i=found->second; swap_nodes(i,heap_.size()-1U); index_.erase(id); heap_.pop_back(); if(i<heap_.size()){ sift_up(i); sift_down(index_[heap_[i].value.id]); } return true; }
std::optional<EmergencyDispatch::Incident> EmergencyDispatch::dispatch_next(){ if(heap_.empty()) return std::nullopt; const auto out=heap_[0].value; cancel(out.id); return out; }
bool EmergencyDispatch::debug_valid_heap() const { if(index_.size()!=heap_.size()) return false; for(std::size_t i=0;i<heap_.size();++i){ const auto f=index_.find(heap_[i].value.id); if(f==index_.end()||f->second!=i) return false; if(i&&better(heap_[i],heap_[(i-1U)/2U])) return false; } return true; }''', "indexed-binary-max-heap")
    s = _source('''bool EmergencyDispatch::better(const Node&,const Node&){return false;} void EmergencyDispatch::swap_nodes(std::size_t,std::size_t){} void EmergencyDispatch::sift_up(std::size_t){} void EmergencyDispatch::sift_down(std::size_t){} bool EmergencyDispatch::report(int,int,int){return false;} bool EmergencyDispatch::revise(int,int,int){return false;} bool EmergencyDispatch::cancel(int){return false;} std::optional<EmergencyDispatch::Incident> EmergencyDispatch::dispatch_next(){return std::nullopt;} bool EmergencyDispatch::debug_valid_heap() const{return false;}''', "indexed-binary-max-heap")
    v = _test('''EmergencyDispatch q; check(q.report(1,5,20)); check(q.report(2,5,10)); check(q.report(3,2,1)); check(q.revise(3,9,30)); auto a=q.dispatch_next(); check(a&&a->id==3); check(q.cancel(1)); auto b=q.dispatch_next(); check(b&&b->id==2); check(!q.dispatch_next()); check(q.debug_valid_heap());''')
    x = _test('''EmergencyDispatch q; for(int i=1;i<=80;++i) check(q.report(i,i%11,100-i)); for(int i=1;i<=80;i+=3) check(q.revise(i,30-i%5,i)); for(int i=2;i<=80;i+=5) q.cancel(i); int prior=1000; while(auto item=q.dispatch_next()){ check(item->severity<=prior); prior=item->severity; check(q.debug_valid_heap()); } check(q.pending()==0U);''')
    return Case("pq-emergency-dispatch","EmergencyDispatch","indexed-binary-max-heap","Mutable indexed max-heap with stable admission ties.",h,r,s,v,x,("sift_up","sift_down","index_["))


def _build_scheduler() -> Case:
    h = _header('''class BuildScheduler {
public:
  struct Job { int id; int priority; int duration; int dependencies; };
  bool add_job(Job); bool complete_dependency(int id); std::optional<Job> start_next(); std::size_t blocked() const; bool debug_valid_heap() const;
private:
  std::vector<Job> heap_; std::unordered_map<int,Job> blocked_; std::unordered_set<int> ids_;
  static bool better(const Job&,const Job&); void sift_up(std::size_t); void sift_down(std::size_t);
};''')
    r = _source('''bool BuildScheduler::better(const Job&a,const Job&b){return a.priority!=b.priority?a.priority>b.priority:a.duration!=b.duration?a.duration<b.duration:a.id<b.id;}
void BuildScheduler::sift_up(std::size_t i){while(i){auto p=(i-1U)/4U;if(!better(heap_[i],heap_[p]))break;std::swap(heap_[i],heap_[p]);i=p;}}
void BuildScheduler::sift_down(std::size_t i){for(;;){auto best=i;for(std::size_t k=1;k<=4;++k){auto c=4U*i+k;if(c<heap_.size()&&better(heap_[c],heap_[best]))best=c;}if(best==i)break;std::swap(heap_[i],heap_[best]);i=best;}}
bool BuildScheduler::add_job(Job j){if(j.id<=0||j.priority<0||j.duration<=0||j.dependencies<0||ids_.count(j.id))return false;ids_.insert(j.id);if(j.dependencies)blocked_[j.id]=j;else{heap_.push_back(j);sift_up(heap_.size()-1U);}return true;}
bool BuildScheduler::complete_dependency(int id){auto it=blocked_.find(id);if(it==blocked_.end())return false;if(--it->second.dependencies==0){heap_.push_back(it->second);blocked_.erase(it);sift_up(heap_.size()-1U);}return true;}
std::optional<BuildScheduler::Job> BuildScheduler::start_next(){if(heap_.empty())return std::nullopt;Job out=heap_[0];ids_.erase(out.id);heap_[0]=heap_.back();heap_.pop_back();if(!heap_.empty())sift_down(0);return out;}
std::size_t BuildScheduler::blocked()const{return blocked_.size();}
bool BuildScheduler::debug_valid_heap()const{for(std::size_t i=1;i<heap_.size();++i)if(better(heap_[i],heap_[(i-1U)/4U]))return false;return ids_.size()==heap_.size()+blocked_.size();}''',"four-ary-ready-heap")
    s = _source('''bool BuildScheduler::better(const Job&,const Job&){return false;}void BuildScheduler::sift_up(std::size_t){}void BuildScheduler::sift_down(std::size_t){}bool BuildScheduler::add_job(Job){return false;}bool BuildScheduler::complete_dependency(int){return false;}std::optional<BuildScheduler::Job> BuildScheduler::start_next(){return std::nullopt;}std::size_t BuildScheduler::blocked()const{return 0;}bool BuildScheduler::debug_valid_heap()const{return false;}''',"four-ary-ready-heap")
    v=_test('''BuildScheduler q;check(q.add_job({1,9,8,2}));check(q.add_job({2,5,2,0}));check(q.blocked()==1U);check(q.complete_dependency(1));check(q.complete_dependency(1));auto a=q.start_next();check(a&&a->id==1);auto b=q.start_next();check(b&&b->id==2);check(q.debug_valid_heap());''')
    x=_test('''BuildScheduler q;for(int i=1;i<=100;++i)check(q.add_job({i,i%17,101-i,i%3}));for(int i=1;i<=100;++i){q.complete_dependency(i);q.complete_dependency(i);}int count=0;while(q.start_next())++count;check(count==100);check(q.blocked()==0U);check(q.debug_valid_heap());''')
    return Case("pq-build-scheduler","BuildScheduler","four-ary-ready-heap","Dependency-blocked jobs enter a four-ary ready heap.",h,r,s,v,x,("/4U","k<=4","blocked_"))


def _flight() -> Case:
    h=_header('''class FlightStandby { public: struct Passenger{int id;int tier;}; bool join(int id,int tier);bool change_tier(int id,int tier);bool withdraw(int id);std::optional<Passenger> promote_next();std::size_t waiting()const{return live_.size();}bool debug_valid_heap()const; private:struct Ticket{int id;std::size_t version;};struct State{int tier;std::size_t version;};std::array<std::deque<Ticket>,4> buckets_;std::unordered_map<int,State> live_;std::size_t version_=0;};''')
    r=_source('''bool FlightStandby::join(int id,int tier){if(id<=0||tier<0||tier>3||live_.count(id))return false;live_[id]={tier,++version_};buckets_[static_cast<std::size_t>(tier)].push_back({id,version_});return true;}bool FlightStandby::change_tier(int id,int tier){auto it=live_.find(id);if(it==live_.end()||tier<0||tier>3)return false;it->second={tier,++version_};buckets_[static_cast<std::size_t>(tier)].push_back({id,version_});return true;}bool FlightStandby::withdraw(int id){return live_.erase(id)!=0U;}std::optional<FlightStandby::Passenger> FlightStandby::promote_next(){for(int tier=3;tier>=0;--tier){auto& q=buckets_[static_cast<std::size_t>(tier)];while(!q.empty()){auto t=q.front();q.pop_front();auto it=live_.find(t.id);if(it==live_.end()||it->second.version!=t.version||it->second.tier!=tier)continue;Passenger out{t.id,tier};live_.erase(it);return out;}}return std::nullopt;}bool FlightStandby::debug_valid_heap()const{for(const auto& item:live_)if(item.second.tier<0||item.second.tier>3)return false;return true;}''',"tiered-fifo-buckets")
    s=_source('''bool FlightStandby::join(int,int){return false;}bool FlightStandby::change_tier(int,int){return false;}bool FlightStandby::withdraw(int){return false;}std::optional<FlightStandby::Passenger> FlightStandby::promote_next(){return std::nullopt;}bool FlightStandby::debug_valid_heap()const{return false;}''',"tiered-fifo-buckets")
    v=_test('''FlightStandby q;check(q.join(1,1));check(q.join(2,3));check(q.join(3,3));check(q.change_tier(1,3));check(q.promote_next()->id==2);check(q.withdraw(3));check(q.promote_next()->id==1);check(!q.promote_next());''')
    x=_test('''FlightStandby q;for(int i=1;i<=120;++i)check(q.join(i,i%4));for(int i=1;i<=120;i+=2)check(q.change_tier(i,3));for(int i=4;i<=120;i+=4)q.withdraw(i);int count=0;while(q.promote_next())++count;check(count==90);check(q.waiting()==0U);check(q.debug_valid_heap());''')
    return Case("pq-flight-standby","FlightStandby","tiered-fifo-buckets","Four priority buckets use FIFO and versioned tier changes.",h,r,s,v,x,("buckets_","version","for(int tier=3"))


def _print() -> Case:
    h=_header('''class PrintRouting{public:bool submit(int id,bool urgent);bool cancel(int id);std::optional<int> route_next();std::size_t pending()const{return live_.size();}bool debug_valid_heap()const;private:std::deque<int> urgent_,normal_;std::unordered_set<int> live_;unsigned cycle_=0;std::optional<int> take(std::deque<int>&);};''')
    r=_source('''bool PrintRouting::submit(int id,bool urgent){if(id<=0||live_.count(id))return false;live_.insert(id);(urgent?urgent_:normal_).push_back(id);return true;}bool PrintRouting::cancel(int id){return live_.erase(id)!=0U;}std::optional<int> PrintRouting::take(std::deque<int>&q){while(!q.empty()){int id=q.front();q.pop_front();if(live_.erase(id))return id;}return std::nullopt;}std::optional<int> PrintRouting::route_next(){for(int attempts=0;attempts<3;++attempts){const bool want_urgent=cycle_!=2U;cycle_=(cycle_+1U)%3U;if(auto id=want_urgent?take(urgent_):take(normal_))return id;}if(auto id=take(urgent_))return id;return take(normal_);}bool PrintRouting::debug_valid_heap()const{return cycle_<3U;}''',"weighted-two-lane-cycle")
    s=_source('''bool PrintRouting::submit(int,bool){return false;}bool PrintRouting::cancel(int){return false;}std::optional<int> PrintRouting::take(std::deque<int>&){return std::nullopt;}std::optional<int> PrintRouting::route_next(){return std::nullopt;}bool PrintRouting::debug_valid_heap()const{return false;}''',"weighted-two-lane-cycle")
    v=_test('''PrintRouting q;check(q.submit(1,true));check(q.submit(2,true));check(q.submit(3,true));check(q.submit(4,false));check(q.submit(5,false));check(q.route_next()==1);check(q.route_next()==2);check(q.route_next()==4);check(q.route_next()==3);check(q.route_next()==5);''')
    x=_test('''PrintRouting q;for(int i=1;i<=60;++i)check(q.submit(i,i%2==0));for(int i=5;i<=60;i+=5)q.cancel(i);int count=0;while(q.route_next())++count;check(count==48);check(q.pending()==0U);check(q.debug_valid_heap());''')
    return Case("pq-print-routing","PrintRouting","weighted-two-lane-cycle","Two FIFO lanes follow a two-urgent/one-normal service cycle.",h,r,s,v,x,("cycle_","urgent_","normal_"))


def _hospital() -> Case:
    h=_header('''class HospitalTriage{public:struct Patient{int id;int acuity;int admitted_at;};bool admit(int id,int acuity);bool advance_minutes(int minutes);bool discharge(int id);std::optional<Patient> select_next();std::size_t pending()const{return live_.size();}bool debug_valid_heap()const;private:struct State{Patient patient;std::size_t version;std::size_t admission;};struct Ticket{int id;std::size_t version;};std::array<std::deque<Ticket>,5>buckets_;std::unordered_map<int,State>live_;int now_=0;std::size_t version_=0,sequence_=0;void rebucket();};''')
    r=_source('''bool HospitalTriage::admit(int id,int acuity){if(id<=0||acuity<1||acuity>5||live_.count(id))return false;live_[id]={{id,acuity,now_},++version_,++sequence_};buckets_[static_cast<std::size_t>(acuity-1)].push_back({id,version_});return true;}bool HospitalTriage::advance_minutes(int minutes){if(minutes<0)return false;now_+=minutes;rebucket();return true;}void HospitalTriage::rebucket(){std::array<std::deque<Ticket>,5> next;std::vector<int>order;for(const auto&pair:live_){auto at=order.end();while(at!=order.begin()&&live_.at(*(at-1)).admission>pair.second.admission)--at;order.insert(at,pair.first);}for(int id:order){auto&state=live_.at(id);const int effective=std::min(5,state.patient.acuity+(now_-state.patient.admitted_at)/10);state.version=++version_;next[static_cast<std::size_t>(effective-1)].push_back({id,state.version});}buckets_=std::move(next);}bool HospitalTriage::discharge(int id){return live_.erase(id)!=0U;}std::optional<HospitalTriage::Patient> HospitalTriage::select_next(){for(int a=4;a>=0;--a){auto&q=buckets_[static_cast<std::size_t>(a)];while(!q.empty()){auto t=q.front();q.pop_front();auto it=live_.find(t.id);if(it==live_.end()||it->second.version!=t.version)continue;auto out=it->second.patient;live_.erase(it);return out;}}return std::nullopt;}bool HospitalTriage::debug_valid_heap()const{for(const auto&q:buckets_){std::size_t prior=0;for(const auto&t:q){auto it=live_.find(t.id);if(it!=live_.end()&&it->second.version==t.version){if(it->second.admission<prior)return false;prior=it->second.admission;}}}return now_>=0;}''',"aging-acuity-buckets")
    s=_source('''bool HospitalTriage::admit(int,int){return false;}bool HospitalTriage::advance_minutes(int){return false;}void HospitalTriage::rebucket(){}bool HospitalTriage::discharge(int){return false;}std::optional<HospitalTriage::Patient> HospitalTriage::select_next(){return std::nullopt;}bool HospitalTriage::debug_valid_heap()const{return false;}''',"aging-acuity-buckets")
    v=_test('''HospitalTriage q;check(q.admit(1,1));check(q.admit(2,4));check(q.advance_minutes(30));check(q.select_next()->id==2);check(q.select_next()->id==1);check(!q.advance_minutes(-1));''')
    x=_test('''HospitalTriage q;for(int i=1;i<=50;++i)check(q.admit(i,1+i%5));check(q.advance_minutes(47));for(int i=3;i<=50;i+=3)q.discharge(i);check(q.debug_valid_heap());int count=0;int last_five_id=0;while(auto patient=q.select_next()){if(patient->acuity==5){check(patient->id>last_five_id);last_five_id=patient->id;}++count;check(q.debug_valid_heap());}check(count==34);check(q.pending()==0U);''')
    return Case("pq-hospital-triage","HospitalTriage","aging-acuity-buckets","Five acuity buckets promote patients by waiting epochs.",h,r,s,v,x,("rebucket","/10","buckets_"))


def _network() -> Case:
    h=_header('''class NetworkRetries{public:struct Retry{int id;std::uint64_t deadline;};bool schedule(int id,std::uint64_t deadline);std::optional<Retry> take_due(std::uint64_t limit);std::uint64_t last_popped()const{return last_;}std::size_t pending()const{return size_;}bool debug_valid_heap()const;private:std::array<std::vector<Retry>,65>buckets_;std::unordered_set<int>ids_;std::uint64_t last_=0;std::size_t size_=0;static unsigned bucket(std::uint64_t key,std::uint64_t last);void redistribute();};''')
    r=_source('''unsigned NetworkRetries::bucket(std::uint64_t key,std::uint64_t last){const auto x=key^last;if(!x)return 0;unsigned b=0;for(auto y=x;y;y>>=1U)++b;return b;}bool NetworkRetries::schedule(int id,std::uint64_t deadline){if(id<=0||deadline<last_||ids_.count(id))return false;buckets_[bucket(deadline,last_)].push_back({id,deadline});ids_.insert(id);++size_;return true;}void NetworkRetries::redistribute(){std::size_t b=1;while(b<buckets_.size()&&buckets_[b].empty())++b;if(b==buckets_.size())return;auto minimum=buckets_[b][0].deadline;for(const auto&x:buckets_[b])minimum=std::min(minimum,x.deadline);last_=minimum;auto moved=std::move(buckets_[b]);buckets_[b].clear();for(const auto&x:moved)buckets_[bucket(x.deadline,last_)].push_back(x);}std::optional<NetworkRetries::Retry> NetworkRetries::take_due(std::uint64_t limit){if(!size_)return std::nullopt;if(buckets_[0].empty()){std::size_t b=1;while(b<buckets_.size()&&buckets_[b].empty())++b;auto minimum=buckets_[b][0].deadline;for(const auto&x:buckets_[b])minimum=std::min(minimum,x.deadline);if(minimum>limit)return std::nullopt;redistribute();}if(buckets_[0].empty()||last_>limit)return std::nullopt;auto best=std::min_element(buckets_[0].begin(),buckets_[0].end(),[](const Retry&a,const Retry&b){return a.id<b.id;});Retry out=*best;buckets_[0].erase(best);ids_.erase(out.id);--size_;return out;}bool NetworkRetries::debug_valid_heap()const{std::size_t n=0;for(std::size_t b=0;b<buckets_.size();++b)for(const auto&x:buckets_[b]){if(bucket(x.deadline,last_)!=b)return false;++n;}return n==size_;}''',"monotone-radix-heap")
    s=_source('''unsigned NetworkRetries::bucket(std::uint64_t,std::uint64_t){return 0;}bool NetworkRetries::schedule(int,std::uint64_t){return false;}void NetworkRetries::redistribute(){}std::optional<NetworkRetries::Retry> NetworkRetries::take_due(std::uint64_t){return std::nullopt;}bool NetworkRetries::debug_valid_heap()const{return false;}''',"monotone-radix-heap")
    v=_test('''NetworkRetries q;check(q.schedule(1,8));check(q.schedule(2,3));check(!q.take_due(2));check(q.take_due(3)->id==2);check(!q.schedule(3,2));check(q.schedule(3,65));check(q.take_due(8)->id==1);check(q.take_due(70)->id==3);''')
    x=_test('''NetworkRetries q;for(int i=1;i<=200;++i)check(q.schedule(i,static_cast<std::uint64_t>(i*i)));std::uint64_t prior=0;while(auto x=q.take_due(std::numeric_limits<std::uint64_t>::max())){check(x->deadline>=prior);prior=x->deadline;check(q.debug_valid_heap());}check(q.pending()==0U);''')
    return Case("pq-network-retries","NetworkRetries","monotone-radix-heap","A 65-bucket monotone radix heap orders retry deadlines.",h,r,s,v,x,("key^last","redistribute","buckets_[bucket"))


def _warehouse() -> Case:
    h=_header('''class WarehousePicks{public:struct Pick{int id;int zone;int cutoff;};bool add_pick(Pick);std::optional<Pick> dispatch_next();std::size_t pending_in_zone(int)const;std::size_t pending()const{return total_;}bool debug_valid_heap()const;private:struct Head{int zone;int cutoff;};std::unordered_map<int,std::deque<Pick>>zones_;std::vector<Head>heap_;std::unordered_map<int,std::size_t>position_;std::unordered_set<int>ids_;std::size_t total_=0;static bool better(const Head&,const Head&);void swap_heads(std::size_t,std::size_t);void up(std::size_t);void down(std::size_t);void insert_head(int);void remove_root();};''')
    r=_source('''bool WarehousePicks::better(const Head&a,const Head&b){return a.cutoff!=b.cutoff?a.cutoff<b.cutoff:a.zone<b.zone;}void WarehousePicks::swap_heads(std::size_t a,std::size_t b){std::swap(heap_[a],heap_[b]);position_[heap_[a].zone]=a;position_[heap_[b].zone]=b;}void WarehousePicks::up(std::size_t i){while(i){auto p=(i-1U)/2U;if(!better(heap_[i],heap_[p]))break;swap_heads(i,p);i=p;}}void WarehousePicks::down(std::size_t i){for(;;){auto b=i,l=2U*i+1U,r=l+1U;if(l<heap_.size()&&better(heap_[l],heap_[b]))b=l;if(r<heap_.size()&&better(heap_[r],heap_[b]))b=r;if(b==i)break;swap_heads(i,b);i=b;}}void WarehousePicks::insert_head(int z){heap_.push_back({z,zones_[z].front().cutoff});position_[z]=heap_.size()-1U;up(heap_.size()-1U);}void WarehousePicks::remove_root(){int z=heap_[0].zone;swap_heads(0,heap_.size()-1U);heap_.pop_back();position_.erase(z);if(!heap_.empty())down(0);}bool WarehousePicks::add_pick(Pick p){if(p.id<=0||p.zone<0||p.cutoff<0||ids_.count(p.id))return false;auto&q=zones_[p.zone];const bool empty=q.empty();q.push_back(p);ids_.insert(p.id);++total_;if(empty)insert_head(p.zone);return true;}std::optional<WarehousePicks::Pick> WarehousePicks::dispatch_next(){if(heap_.empty())return std::nullopt;int z=heap_[0].zone;auto&q=zones_[z];Pick out=q.front();q.pop_front();ids_.erase(out.id);--total_;remove_root();if(!q.empty())insert_head(z);return out;}std::size_t WarehousePicks::pending_in_zone(int z)const{auto it=zones_.find(z);return it==zones_.end()?0U:it->second.size();}bool WarehousePicks::debug_valid_heap()const{if(heap_.size()!=position_.size())return false;for(std::size_t i=0;i<heap_.size();++i){if(zones_.at(heap_[i].zone).empty()||position_.at(heap_[i].zone)!=i)return false;if(i&&better(heap_[i],heap_[(i-1U)/2U]))return false;}return true;}''',"heap-of-zone-heads")
    s=_source('''bool WarehousePicks::better(const Head&,const Head&){return false;}void WarehousePicks::swap_heads(std::size_t,std::size_t){}void WarehousePicks::up(std::size_t){}void WarehousePicks::down(std::size_t){}void WarehousePicks::insert_head(int){}void WarehousePicks::remove_root(){}bool WarehousePicks::add_pick(Pick){return false;}std::optional<WarehousePicks::Pick> WarehousePicks::dispatch_next(){return std::nullopt;}std::size_t WarehousePicks::pending_in_zone(int)const{return 0;}bool WarehousePicks::debug_valid_heap()const{return false;}''',"heap-of-zone-heads")
    v=_test('''WarehousePicks q;check(q.add_pick({1,7,30}));check(q.add_pick({2,7,1}));check(q.add_pick({3,2,20}));check(q.dispatch_next()->id==3);check(q.dispatch_next()->id==1);check(q.dispatch_next()->id==2);''')
    x=_test('''WarehousePicks q;for(int i=1;i<=150;++i)check(q.add_pick({i,i%9,i%23}));int count=0;while(q.dispatch_next()){++count;check(q.debug_valid_heap());}check(count==150);check(q.pending()==0U);''')
    return Case("pq-warehouse-picks","WarehousePicks","heap-of-zone-heads","A heap contains only the FIFO head of each zone.",h,r,s,v,x,("zones_[z].front","insert_head","position_"))


