def _pairing() -> Case:
    h=_header('''class SnowplowDispatch{public:struct Segment{int id;int hazard;};bool report(int district,int id,int hazard);bool merge_districts(int target,int source);std::optional<Segment> assign_next(int district);std::size_t pending(int district)const;bool debug_valid_heap()const;private:struct Node{Segment value;int child=-1;int sibling=-1;};std::vector<Node>nodes_;std::unordered_map<int,int>roots_;std::unordered_map<int,std::size_t>sizes_;std::unordered_set<int>ids_;static bool better(const Segment&,const Segment&);int meld(int,int);int pop_root(int);};''')
    r=_source('''bool SnowplowDispatch::better(const Segment&a,const Segment&b){return a.hazard!=b.hazard?a.hazard>b.hazard:a.id<b.id;}int SnowplowDispatch::meld(int a,int b){if(a<0)return b;if(b<0)return a;if(better(nodes_[static_cast<std::size_t>(b)].value,nodes_[static_cast<std::size_t>(a)].value))std::swap(a,b);nodes_[static_cast<std::size_t>(b)].sibling=nodes_[static_cast<std::size_t>(a)].child;nodes_[static_cast<std::size_t>(a)].child=b;return a;}int SnowplowDispatch::pop_root(int root){std::vector<int>pairs;int child=nodes_[static_cast<std::size_t>(root)].child;while(child>=0){int a=child;int b=nodes_[static_cast<std::size_t>(a)].sibling;child=b<0?-1:nodes_[static_cast<std::size_t>(b)].sibling;nodes_[static_cast<std::size_t>(a)].sibling=-1;if(b>=0){nodes_[static_cast<std::size_t>(b)].sibling=-1;pairs.push_back(meld(a,b));}else pairs.push_back(a);}int out=-1;for(auto it=pairs.rbegin();it!=pairs.rend();++it)out=meld(out,*it);return out;}bool SnowplowDispatch::report(int d,int id,int hazard){if(d<0||id<=0||hazard<0||ids_.count(id))return false;nodes_.push_back({{id,hazard},-1,-1});ids_.insert(id);roots_[d]=meld(roots_.count(d)?roots_[d]:-1,static_cast<int>(nodes_.size()-1U));++sizes_[d];return true;}bool SnowplowDispatch::merge_districts(int target,int source){if(target<0||source<0||target==source)return false;roots_[target]=meld(roots_.count(target)?roots_[target]:-1,roots_.count(source)?roots_[source]:-1);sizes_[target]+=sizes_[source];roots_[source]=-1;sizes_[source]=0;return true;}std::optional<SnowplowDispatch::Segment> SnowplowDispatch::assign_next(int d){int root=roots_.count(d)?roots_[d]:-1;if(root<0)return std::nullopt;auto out=nodes_[static_cast<std::size_t>(root)].value;roots_[d]=pop_root(root);ids_.erase(out.id);--sizes_[d];return out;}std::size_t SnowplowDispatch::pending(int d)const{auto it=sizes_.find(d);return it==sizes_.end()?0U:it->second;}bool SnowplowDispatch::debug_valid_heap()const{for(const auto&p:roots_){std::vector<int>stack;if(p.second>=0)stack.push_back(p.second);while(!stack.empty()){int n=stack.back();stack.pop_back();for(int c=nodes_[static_cast<std::size_t>(n)].child;c>=0;c=nodes_[static_cast<std::size_t>(c)].sibling){if(better(nodes_[static_cast<std::size_t>(c)].value,nodes_[static_cast<std::size_t>(n)].value))return false;stack.push_back(c);}}}return true;}''',"pairing-heap-meld")
    s=_source('''bool SnowplowDispatch::better(const Segment&,const Segment&){return false;}int SnowplowDispatch::meld(int,int){return -1;}int SnowplowDispatch::pop_root(int){return -1;}bool SnowplowDispatch::report(int,int,int){return false;}bool SnowplowDispatch::merge_districts(int,int){return false;}std::optional<SnowplowDispatch::Segment> SnowplowDispatch::assign_next(int){return std::nullopt;}std::size_t SnowplowDispatch::pending(int)const{return 0;}bool SnowplowDispatch::debug_valid_heap()const{return false;}''',"pairing-heap-meld")
    v=_test('''SnowplowDispatch q;check(q.report(1,1,3));check(q.report(1,2,9));check(q.report(2,3,7));check(q.merge_districts(1,2));check(q.pending(2)==0U);check(q.assign_next(1)->id==2);check(q.assign_next(1)->id==3);check(q.assign_next(1)->id==1);''')
    x=_test('''SnowplowDispatch q;for(int i=1;i<=180;++i)check(q.report(i%12,i,i%31));for(int d=1;d<12;++d)check(q.merge_districts(0,d));int prior=100;while(auto x=q.assign_next(0)){check(x->hazard<=prior);prior=x->hazard;check(q.debug_valid_heap());}check(q.pending(0)==0U);''')
    return Case("pq-road-snowplows","SnowplowDispatch","pairing-heap-meld","District queues are pairing heaps with two-pass delete-root.",h,r,s,v,x,("pop_root","pairs.rbegin","child"))


def _leftist() -> Case:
    h=_header('''class SupportEscalations{public:struct Ticket{int id;int risk;};bool open(int queue,int id,int risk);bool escalate(int id,int new_risk);bool meld_queues(int target,int source);std::optional<Ticket> take_next(int queue);std::size_t pending(int queue)const;bool debug_valid_heap()const;private:struct Node{Ticket value;std::size_t version;int left=-1;int right=-1;int rank=1;};struct Record{int queue;int risk;std::size_t version;};std::vector<Node>nodes_;std::unordered_map<int,int>roots_;std::unordered_map<int,std::size_t>sizes_;std::unordered_map<int,Record>records_;std::size_t version_=0;static bool better(const Ticket&,const Ticket&);int meld(int,int);void insert_snapshot(int);void purge(int);bool valid(int)const;};''')
    r=_source('''bool SupportEscalations::better(const Ticket&a,const Ticket&b){return a.risk!=b.risk?a.risk>b.risk:a.id<b.id;}int SupportEscalations::meld(int a,int b){if(a<0)return b;if(b<0)return a;if(better(nodes_[static_cast<std::size_t>(b)].value,nodes_[static_cast<std::size_t>(a)].value))std::swap(a,b);auto&r=nodes_[static_cast<std::size_t>(a)];r.right=meld(r.right,b);const int lr=r.left<0?0:nodes_[static_cast<std::size_t>(r.left)].rank;const int rr=r.right<0?0:nodes_[static_cast<std::size_t>(r.right)].rank;if(lr<rr)std::swap(r.left,r.right);r.rank=1+(r.right<0?0:nodes_[static_cast<std::size_t>(r.right)].rank);return a;}void SupportEscalations::insert_snapshot(int id){const auto&r=records_.at(id);nodes_.push_back({{id,r.risk},r.version,-1,-1,1});roots_[r.queue]=meld(roots_.count(r.queue)?roots_[r.queue]:-1,static_cast<int>(nodes_.size()-1U));}bool SupportEscalations::open(int q,int id,int risk){if(q<0||id<=0||risk<0||records_.count(id))return false;records_[id]={q,risk,++version_};insert_snapshot(id);++sizes_[q];return true;}bool SupportEscalations::escalate(int id,int new_risk){auto it=records_.find(id);if(it==records_.end()||new_risk<=it->second.risk)return false;it->second.risk=new_risk;it->second.version=++version_;insert_snapshot(id);return true;}bool SupportEscalations::meld_queues(int target,int source){if(target<0||source<0||target==source)return false;for(auto&pair:records_)if(pair.second.queue==source)pair.second.queue=target;roots_[target]=meld(roots_.count(target)?roots_[target]:-1,roots_.count(source)?roots_[source]:-1);sizes_[target]+=sizes_[source];roots_[source]=-1;sizes_[source]=0;return true;}void SupportEscalations::purge(int q){auto&root=roots_[q];while(root>=0){const auto&n=nodes_[static_cast<std::size_t>(root)];auto it=records_.find(n.value.id);if(it!=records_.end()&&it->second.queue==q&&it->second.version==n.version)return;root=meld(n.left,n.right);}}std::optional<SupportEscalations::Ticket> SupportEscalations::take_next(int q){purge(q);int root=roots_[q];if(root<0)return std::nullopt;auto out=nodes_[static_cast<std::size_t>(root)].value;roots_[q]=meld(nodes_[static_cast<std::size_t>(root)].left,nodes_[static_cast<std::size_t>(root)].right);records_.erase(out.id);--sizes_[q];purge(q);return out;}std::size_t SupportEscalations::pending(int q)const{auto it=sizes_.find(q);return it==sizes_.end()?0U:it->second;}bool SupportEscalations::valid(int n)const{if(n<0)return true;const auto&x=nodes_[static_cast<std::size_t>(n)];const int l=x.left<0?0:nodes_[static_cast<std::size_t>(x.left)].rank,r=x.right<0?0:nodes_[static_cast<std::size_t>(x.right)].rank;if(l<r||x.rank!=r+1)return false;if(x.left>=0&&better(nodes_[static_cast<std::size_t>(x.left)].value,x.value))return false;if(x.right>=0&&better(nodes_[static_cast<std::size_t>(x.right)].value,x.value))return false;return valid(x.left)&&valid(x.right);}bool SupportEscalations::debug_valid_heap()const{for(const auto&p:roots_)if(!valid(p.second))return false;return true;}''',"leftist-heap-meld")
    s=_source('''bool SupportEscalations::better(const Ticket&,const Ticket&){return false;}int SupportEscalations::meld(int,int){return -1;}void SupportEscalations::insert_snapshot(int){}bool SupportEscalations::open(int,int,int){return false;}bool SupportEscalations::escalate(int,int){return false;}bool SupportEscalations::meld_queues(int,int){return false;}void SupportEscalations::purge(int){}std::optional<SupportEscalations::Ticket> SupportEscalations::take_next(int){return std::nullopt;}std::size_t SupportEscalations::pending(int)const{return 0;}bool SupportEscalations::valid(int)const{return false;}bool SupportEscalations::debug_valid_heap()const{return false;}''',"leftist-heap-meld")
    v=_test('''SupportEscalations q;check(q.open(1,1,4));check(q.open(1,2,8));check(q.open(2,3,6));check(q.escalate(1,11));check(q.meld_queues(1,2));check(q.take_next(1)->id==1);check(q.take_next(1)->id==2);check(q.debug_valid_heap());''')
    x=_test('''SupportEscalations q;for(int i=1;i<=160;++i)check(q.open(i%16,i,i%29));for(int i=1;i<16;++i)check(q.meld_queues(0,i));int count=0;while(q.take_next(0)){++count;check(q.debug_valid_heap());}check(count==160);''')
    return Case("pq-support-escalations","SupportEscalations","leftist-heap-meld","Mutable escalation creates versioned snapshots in meldable leftist heaps with stored null-path ranks.",h,r,s,v,x,("rank","lr<rr","insert_snapshot"))


def _auction() -> Case:
    h=_header('''class AuctionOrders{public:struct Order{int id;int price;int quantity;};bool place(Order);bool cancel(int id);std::optional<Order> match_next();std::size_t levels()const{return level_count_;}bool debug_valid_heap()const;private:std::unordered_map<int,std::deque<Order>>books_;std::unordered_map<int,int>id_price_;std::unordered_map<int,std::size_t>live_per_price_;std::vector<int>prices_;std::unordered_set<int>active_prices_,live_ids_;std::size_t level_count_=0;void price_up(std::size_t);void price_down(std::size_t);void add_price(int);void purge_root();void remove_live(int,int);};''')
    r=_source('''void AuctionOrders::price_up(std::size_t i){while(i){auto p=(i-1U)/2U;if(prices_[p]>=prices_[i])break;std::swap(prices_[p],prices_[i]);i=p;}}void AuctionOrders::price_down(std::size_t i){for(;;){auto b=i,l=2U*i+1U,r=l+1U;if(l<prices_.size()&&prices_[l]>prices_[b])b=l;if(r<prices_.size()&&prices_[r]>prices_[b])b=r;if(b==i)break;std::swap(prices_[i],prices_[b]);i=b;}}void AuctionOrders::add_price(int p){if(active_prices_.insert(p).second){prices_.push_back(p);price_up(prices_.size()-1U);}}void AuctionOrders::remove_live(int id,int price){live_ids_.erase(id);id_price_.erase(id);auto&count=live_per_price_[price];if(--count==0U)--level_count_;}bool AuctionOrders::place(Order o){if(o.id<=0||o.price<=0||o.quantity<=0||live_ids_.count(o.id))return false;add_price(o.price);books_[o.price].push_back(o);live_ids_.insert(o.id);id_price_[o.id]=o.price;if(live_per_price_[o.price]++==0U)++level_count_;return true;}bool AuctionOrders::cancel(int id){auto it=id_price_.find(id);if(it==id_price_.end())return false;remove_live(id,it->second);return true;}void AuctionOrders::purge_root(){while(!prices_.empty()){int p=prices_[0];auto&q=books_[p];while(!q.empty()&&!live_ids_.count(q.front().id))q.pop_front();if(!q.empty())return;active_prices_.erase(p);prices_[0]=prices_.back();prices_.pop_back();if(!prices_.empty())price_down(0);}}std::optional<AuctionOrders::Order> AuctionOrders::match_next(){purge_root();if(prices_.empty())return std::nullopt;auto&q=books_[prices_[0]];auto out=q.front();q.pop_front();remove_live(out.id,out.price);purge_root();return out;}bool AuctionOrders::debug_valid_heap()const{std::size_t levels=0;for(const auto&entry:live_per_price_)if(entry.second)++levels;if(levels!=level_count_||id_price_.size()!=live_ids_.size())return false;for(std::size_t i=1;i<prices_.size();++i)if(prices_[i]>prices_[(i-1U)/2U])return false;return true;}''',"price-level-book")
    s=_source('''void AuctionOrders::price_up(std::size_t){}void AuctionOrders::price_down(std::size_t){}void AuctionOrders::add_price(int){}void AuctionOrders::remove_live(int,int){}bool AuctionOrders::place(Order){return false;}bool AuctionOrders::cancel(int){return false;}void AuctionOrders::purge_root(){}std::optional<AuctionOrders::Order> AuctionOrders::match_next(){return std::nullopt;}bool AuctionOrders::debug_valid_heap()const{return false;}''',"price-level-book")
    v=_test('''AuctionOrders q;check(q.place({1,100,2}));check(q.place({2,110,1}));check(q.place({3,100,4}));check(q.match_next()->id==2);check(q.match_next()->id==1);check(q.cancel(3));check(!q.match_next());''')
    x=_test('''AuctionOrders q;for(int i=1;i<=120;++i)check(q.place({i,90+i%7,1}));for(int i=4;i<=120;i+=4)q.cancel(i);int count=0;while(q.match_next()){++count;check(q.debug_valid_heap());}check(count==90);check(q.levels()==0U);''')
    return Case("pq-auction-orders","AuctionOrders","price-level-book","A max-heap selects FIFO price levels, not individual orders.",h,r,s,v,x,("books_","active_prices_","purge_root"))


def _video() -> Case:
    h=_header('''class VideoTranscodes{public:struct Job{int id;int remaining;};bool submit(int id,int remaining);std::optional<Job> start_or_preempt();bool consume(int ticks);std::optional<Job> finish_current();std::optional<Job> current()const{return running_;}std::size_t waiting()const{return heap_.size();}bool debug_valid_heap()const;private:std::vector<Job>heap_;std::optional<Job>running_;std::unordered_set<int>ids_;static bool better(const Job&,const Job&);void up(std::size_t);void down(std::size_t);Job pop();};''')
    r=_source('''bool VideoTranscodes::better(const Job&a,const Job&b){return a.remaining!=b.remaining?a.remaining<b.remaining:a.id<b.id;}void VideoTranscodes::up(std::size_t i){while(i){auto p=(i-1U)/2U;if(!better(heap_[i],heap_[p]))break;std::swap(heap_[i],heap_[p]);i=p;}}void VideoTranscodes::down(std::size_t i){for(;;){auto b=i,l=2U*i+1U,r=l+1U;if(l<heap_.size()&&better(heap_[l],heap_[b]))b=l;if(r<heap_.size()&&better(heap_[r],heap_[b]))b=r;if(b==i)break;std::swap(heap_[i],heap_[b]);i=b;}}VideoTranscodes::Job VideoTranscodes::pop(){Job out=heap_[0];heap_[0]=heap_.back();heap_.pop_back();if(!heap_.empty())down(0);return out;}bool VideoTranscodes::submit(int id,int remaining){if(id<=0||remaining<=0||ids_.count(id))return false;ids_.insert(id);heap_.push_back({id,remaining});up(heap_.size()-1U);return true;}std::optional<VideoTranscodes::Job> VideoTranscodes::start_or_preempt(){if(!running_){if(heap_.empty())return std::nullopt;running_=pop();}else if(!heap_.empty()&&better(heap_[0],*running_)){heap_.push_back(*running_);up(heap_.size()-1U);running_=pop();}return running_;}bool VideoTranscodes::consume(int ticks){if(!running_||ticks<=0||ticks>running_->remaining)return false;running_->remaining-=ticks;return true;}std::optional<VideoTranscodes::Job> VideoTranscodes::finish_current(){if(!running_||running_->remaining!=0)return std::nullopt;auto out=running_;ids_.erase(out->id);running_.reset();return out;}bool VideoTranscodes::debug_valid_heap()const{for(std::size_t i=1;i<heap_.size();++i)if(better(heap_[i],heap_[(i-1U)/2U]))return false;return ids_.size()==heap_.size()+(running_?1U:0U);}''',"srpt-preemptive-heap")
    s=_source('''bool VideoTranscodes::better(const Job&,const Job&){return false;}void VideoTranscodes::up(std::size_t){}void VideoTranscodes::down(std::size_t){}VideoTranscodes::Job VideoTranscodes::pop(){return {};}bool VideoTranscodes::submit(int,int){return false;}std::optional<VideoTranscodes::Job> VideoTranscodes::start_or_preempt(){return std::nullopt;}bool VideoTranscodes::consume(int){return false;}std::optional<VideoTranscodes::Job> VideoTranscodes::finish_current(){return std::nullopt;}bool VideoTranscodes::debug_valid_heap()const{return false;}''',"srpt-preemptive-heap")
    v=_test('''VideoTranscodes q;check(q.submit(1,10));check(q.start_or_preempt()->id==1);check(q.consume(3));check(q.submit(2,2));check(q.start_or_preempt()->id==2);check(q.consume(2));check(q.finish_current()->id==2);check(q.start_or_preempt()->id==1);''')
    x=_test('''VideoTranscodes q;for(int i=1;i<=80;++i)check(q.submit(i,1+i%17));int done=0;while(done<80){auto j=q.start_or_preempt();check(bool(j));check(q.consume(j->remaining));check(q.finish_current().has_value());++done;check(q.debug_valid_heap());}''')
    return Case("pq-video-transcodes","VideoTranscodes","srpt-preemptive-heap","A waiting min-heap interacts with an explicit preemptible running slot.",h,r,s,v,x,("running_","start_or_preempt","consume("))


def _calendar() -> Case:
    h=_header('''class DataBackups{public:struct Backup{int id;std::uint64_t day;};bool schedule(int id,std::uint64_t day);bool advance_to(std::uint64_t day);std::optional<Backup> take_due();std::size_t pending()const{return ids_.size();}bool debug_valid_heap()const;private:std::array<std::deque<Backup>,32>buckets_;std::unordered_set<int>ids_;std::uint64_t now_=0;std::uint64_t due_cursor_=0;};''')
    r=_source('''bool DataBackups::schedule(int id,std::uint64_t day){if(id<=0||day<now_||day-now_>31U||ids_.count(id))return false;buckets_[static_cast<std::size_t>(day%32U)].push_back({id,day});ids_.insert(id);return true;}bool DataBackups::advance_to(std::uint64_t day){if(day<now_)return false;now_=day;return true;}std::optional<DataBackups::Backup> DataBackups::take_due(){while(due_cursor_<=now_){auto&q=buckets_[static_cast<std::size_t>(due_cursor_%32U)];while(!q.empty()&&q.front().day<due_cursor_)q.pop_front();if(!q.empty()&&q.front().day==due_cursor_){auto out=q.front();q.pop_front();ids_.erase(out.id);return out;}++due_cursor_;}return std::nullopt;}bool DataBackups::debug_valid_heap()const{for(const auto&q:buckets_)for(const auto&b:q)if(b.day%32U>=32U)return false;return due_cursor_<=now_+1U;}''',"circular-calendar-queue")
    s=_source('''bool DataBackups::schedule(int,std::uint64_t){return false;}bool DataBackups::advance_to(std::uint64_t){return false;}std::optional<DataBackups::Backup> DataBackups::take_due(){return std::nullopt;}bool DataBackups::debug_valid_heap()const{return false;}''',"circular-calendar-queue")
    v=_test('''DataBackups q;check(q.schedule(1,31));check(q.schedule(2,2));check(!q.schedule(3,32));check(q.advance_to(2));check(q.take_due()->id==2);check(q.advance_to(31));check(q.take_due()->id==1);''')
    x=_test('''DataBackups q;for(int i=1;i<=31;++i)check(q.schedule(i,static_cast<std::uint64_t>(i)));for(int d=1;d<=31;++d){check(q.advance_to(static_cast<std::uint64_t>(d)));check(q.take_due()->day==static_cast<std::uint64_t>(d));check(q.debug_valid_heap());}check(q.pending()==0U);''')
    return Case("pq-data-backups","DataBackups","circular-calendar-queue","A 32-slot calendar queue handles a bounded monotone horizon.",h,r,s,v,x,("%32U","due_cursor_","buckets_["))


