def _minmax() -> Case:
    h=_header('''class PackageDelivery{public:struct Parcel{int id;int window;};explicit PackageDelivery(std::size_t capacity);bool accept(int id,int window);std::optional<Parcel> dispatch_earliest();std::optional<Parcel> remove_latest();std::optional<int> min_window()const;std::optional<int> max_window()const;std::size_t pending()const{return heap_.size();}bool debug_valid_heap()const;private:std::size_t capacity_;std::vector<Parcel>heap_;std::unordered_set<int>ids_;static bool less(const Parcel&,const Parcel&);static bool min_level(std::size_t);void bubble_min(std::size_t);void bubble_max(std::size_t);void trickle_min(std::size_t);void trickle_max(std::size_t);std::size_t extreme_descendant(std::size_t,bool)const;};''')
    r=_source('''bool PackageDelivery::less(const Parcel&a,const Parcel&b){return a.window!=b.window?a.window<b.window:a.id<b.id;}PackageDelivery::PackageDelivery(std::size_t c):capacity_(c){if(!c)throw std::invalid_argument("capacity");}bool PackageDelivery::min_level(std::size_t i){std::size_t level=0;for(++i;i>1U;i>>=1U)++level;return level%2U==0U;}void PackageDelivery::bubble_min(std::size_t i){while(i>=3U){auto g=(i-3U)/4U;if(!less(heap_[i],heap_[g]))break;std::swap(heap_[i],heap_[g]);i=g;}}void PackageDelivery::bubble_max(std::size_t i){while(i>=3U){auto g=(i-3U)/4U;if(!less(heap_[g],heap_[i]))break;std::swap(heap_[i],heap_[g]);i=g;}}bool PackageDelivery::accept(int id,int window){if(id<=0||window<0||heap_.size()==capacity_||ids_.count(id))return false;ids_.insert(id);heap_.push_back({id,window});auto i=heap_.size()-1U;if(!i)return true;auto p=(i-1U)/2U;if(min_level(i)){if(less(heap_[p],heap_[i])){std::swap(heap_[p],heap_[i]);bubble_max(p);}else bubble_min(i);}else{if(less(heap_[i],heap_[p])){std::swap(heap_[p],heap_[i]);bubble_min(p);}else bubble_max(i);}return true;}std::size_t PackageDelivery::extreme_descendant(std::size_t i,bool want_min)const{auto best=heap_.size();const std::array<std::size_t,6> candidates{{2U*i+1U,2U*i+2U,4U*i+3U,4U*i+4U,4U*i+5U,4U*i+6U}};for(auto c:candidates)if(c<heap_.size()&&(best==heap_.size()||(want_min?less(heap_[c],heap_[best]):less(heap_[best],heap_[c]))))best=c;return best;}void PackageDelivery::trickle_min(std::size_t i){for(;;){auto m=extreme_descendant(i,true);if(m==heap_.size())return;const bool grand=m>=4U*i+3U;if(grand){if(!less(heap_[m],heap_[i]))return;std::swap(heap_[m],heap_[i]);auto p=(m-1U)/2U;if(less(heap_[p],heap_[m]))std::swap(heap_[p],heap_[m]);i=m;}else{if(less(heap_[m],heap_[i]))std::swap(heap_[m],heap_[i]);return;}}}void PackageDelivery::trickle_max(std::size_t i){for(;;){auto m=extreme_descendant(i,false);if(m==heap_.size())return;const bool grand=m>=4U*i+3U;if(grand){if(!less(heap_[i],heap_[m]))return;std::swap(heap_[m],heap_[i]);auto p=(m-1U)/2U;if(less(heap_[m],heap_[p]))std::swap(heap_[p],heap_[m]);i=m;}else{if(less(heap_[i],heap_[m]))std::swap(heap_[m],heap_[i]);return;}}}std::optional<PackageDelivery::Parcel> PackageDelivery::dispatch_earliest(){if(heap_.empty())return std::nullopt;auto out=heap_[0];ids_.erase(out.id);heap_[0]=heap_.back();heap_.pop_back();if(!heap_.empty())trickle_min(0);return out;}std::optional<PackageDelivery::Parcel> PackageDelivery::remove_latest(){if(heap_.empty())return std::nullopt;std::size_t i=0;if(heap_.size()>1U)i=1;if(heap_.size()>2U&&less(heap_[i],heap_[2]))i=2;auto out=heap_[i];ids_.erase(out.id);heap_[i]=heap_.back();heap_.pop_back();if(i<heap_.size())trickle_max(i);return out;}std::optional<int> PackageDelivery::min_window()const{return heap_.empty()?std::nullopt:std::optional<int>(heap_[0].window);}std::optional<int> PackageDelivery::max_window()const{if(heap_.empty())return std::nullopt;std::size_t i=heap_.size()>1U?1U:0U;if(heap_.size()>2U&&less(heap_[i],heap_[2]))i=2;return heap_[i].window;}bool PackageDelivery::debug_valid_heap()const{if(ids_.size()!=heap_.size())return false;for(std::size_t i=0;i<heap_.size();++i){for(auto c:{2U*i+1U,2U*i+2U,4U*i+3U,4U*i+4U,4U*i+5U,4U*i+6U})if(c<heap_.size()){if(min_level(i)&&less(heap_[c],heap_[i]))return false;if(!min_level(i)&&less(heap_[i],heap_[c]))return false;}}return true;}''',"min-max-heap")
    s=_source('''bool PackageDelivery::less(const Parcel&,const Parcel&){return false;}PackageDelivery::PackageDelivery(std::size_t c):capacity_(c){}bool PackageDelivery::min_level(std::size_t){return false;}void PackageDelivery::bubble_min(std::size_t){}void PackageDelivery::bubble_max(std::size_t){}void PackageDelivery::trickle_min(std::size_t){}void PackageDelivery::trickle_max(std::size_t){}std::size_t PackageDelivery::extreme_descendant(std::size_t,bool)const{return heap_.size();}bool PackageDelivery::accept(int,int){return false;}std::optional<PackageDelivery::Parcel> PackageDelivery::dispatch_earliest(){return std::nullopt;}std::optional<PackageDelivery::Parcel> PackageDelivery::remove_latest(){return std::nullopt;}std::optional<int> PackageDelivery::min_window()const{return std::nullopt;}std::optional<int> PackageDelivery::max_window()const{return std::nullopt;}bool PackageDelivery::debug_valid_heap()const{return false;}''',"min-max-heap")
    v=_test('''PackageDelivery q(4);check(q.accept(1,20));check(q.accept(2,5));check(q.accept(3,30));check(q.min_window()==5);check(q.max_window()==30);check(q.dispatch_earliest()->id==2);check(q.remove_latest()->id==3);check(q.debug_valid_heap());''')
    x=_test('''PackageDelivery q(100);for(int i=1;i<=100;++i)check(q.accept(i,(i*37)%211));int prior=-1;for(int i=0;i<50;++i){auto x=q.dispatch_earliest();check(x&&x->window>=prior);prior=x->window;check(q.debug_valid_heap());}for(int i=0;i<50;++i){check(q.remove_latest().has_value());check(q.debug_valid_heap());}check(q.pending()==0U);''')
    return Case("pq-package-delivery","PackageDelivery","min-max-heap","One alternating-level min-max heap supports bounded minimum and maximum removal.",h,r,s,v,x,("min_level","trickle_min","trickle_max"))


def _matchmaking() -> Case:
    h=_header('''class GameMatchmaking{public:struct Match{int first;int second;int gap;};bool join(int id,int rating);bool leave(int id);std::optional<Match> make_match();std::size_t waiting()const{return players_.size();}bool debug_valid_heap()const;private:struct Player{int id;int rating;std::size_t sequence;};struct Candidate{int a;int b;int gap;std::size_t tie;};std::vector<Player>players_;std::vector<Candidate>gaps_;std::size_t sequence_=0;static bool player_less(const Player&,const Player&);static bool candidate_better(const Candidate&,const Candidate&);void rebuild_candidates();void gap_down(std::size_t);};''')
    r=_source('''bool GameMatchmaking::player_less(const Player&a,const Player&b){return a.rating!=b.rating?a.rating<b.rating:a.sequence<b.sequence;}bool GameMatchmaking::candidate_better(const Candidate&a,const Candidate&b){return a.gap!=b.gap?a.gap<b.gap:a.tie!=b.tie?a.tie<b.tie:a.a<b.a;}void GameMatchmaking::gap_down(std::size_t i){for(;;){auto b=i,l=2U*i+1U,r=l+1U;if(l<gaps_.size()&&candidate_better(gaps_[l],gaps_[b]))b=l;if(r<gaps_.size()&&candidate_better(gaps_[r],gaps_[b]))b=r;if(b==i)break;std::swap(gaps_[i],gaps_[b]);i=b;}}void GameMatchmaking::rebuild_candidates(){for(std::size_t i=1;i<players_.size();++i){auto x=players_[i];auto j=i;while(j&&player_less(x,players_[j-1U])){players_[j]=players_[j-1U];--j;}players_[j]=x;}gaps_.clear();for(std::size_t i=1;i<players_.size();++i)gaps_.push_back({players_[i-1U].id,players_[i].id,players_[i].rating-players_[i-1U].rating,std::max(players_[i].sequence,players_[i-1U].sequence)});if(!gaps_.empty())for(std::size_t i=gaps_.size()/2U;i-- >0U;)gap_down(i);}bool GameMatchmaking::join(int id,int rating){if(id<=0||rating<0) return false;for(const auto&p:players_)if(p.id==id)return false;players_.push_back({id,rating,sequence_++});rebuild_candidates();return true;}bool GameMatchmaking::leave(int id){auto it=std::find_if(players_.begin(),players_.end(),[id](const Player&p){return p.id==id;});if(it==players_.end())return false;players_.erase(it);rebuild_candidates();return true;}std::optional<GameMatchmaking::Match> GameMatchmaking::make_match(){if(gaps_.empty())return std::nullopt;auto best=gaps_[0];leave(best.a);leave(best.b);return Match{best.a,best.b,best.gap};}bool GameMatchmaking::debug_valid_heap()const{for(std::size_t i=1;i<players_.size();++i)if(player_less(players_[i],players_[i-1U]))return false;for(std::size_t i=1;i<gaps_.size();++i)if(candidate_better(gaps_[i],gaps_[(i-1U)/2U]))return false;return gaps_.size()==(players_.empty()?0U:players_.size()-1U);}''',"adjacent-gap-candidate-heap")
    s=_source('''bool GameMatchmaking::player_less(const Player&,const Player&){return false;}bool GameMatchmaking::candidate_better(const Candidate&,const Candidate&){return false;}void GameMatchmaking::gap_down(std::size_t){}void GameMatchmaking::rebuild_candidates(){}bool GameMatchmaking::join(int,int){return false;}bool GameMatchmaking::leave(int){return false;}std::optional<GameMatchmaking::Match> GameMatchmaking::make_match(){return std::nullopt;}bool GameMatchmaking::debug_valid_heap()const{return false;}''',"adjacent-gap-candidate-heap")
    v=_test('''GameMatchmaking q;check(q.join(1,1000));check(q.join(2,1010));check(q.join(3,1400));auto m=q.make_match();check(m&&m->first==1&&m->second==2&&m->gap==10);check(q.waiting()==1U);''')
    x=_test('''GameMatchmaking q;for(int i=1;i<=101;++i)check(q.join(i,(i*97)%1600));int matches=0;while(auto m=q.make_match()){check(m->gap>=0);++matches;check(q.debug_valid_heap());}check(matches==50);check(q.waiting()==1U);''')
    return Case("pq-game-matchmaking","GameMatchmaking","adjacent-gap-candidate-heap","A heap of adjacent-rating gaps selects the closest pair.",h,r,s,v,x,("rebuild_candidates","gaps_","player_less"))


def _memory() -> Case:
    h=_header('''class MemoryReclaimer{public:struct Block{int id;int score;bool pinned;};bool track(int id,int score);bool rescore(int id,int score);bool set_pinned(int id,bool pinned);std::optional<Block> reclaim_next();std::size_t pending()const{return records_.size();}bool debug_valid_heap()const;private:struct Record{int score;bool pinned;std::size_t version;};struct Snapshot{int id;int score;std::size_t version;};std::unordered_map<int,Record>records_;std::vector<Snapshot>heap_;std::size_t version_=0;static bool better(const Snapshot&,const Snapshot&);void up(std::size_t);void down(std::size_t);void push_snapshot(int);void purge();};''')
    r=_source('''bool MemoryReclaimer::better(const Snapshot&a,const Snapshot&b){return a.score!=b.score?a.score>b.score:a.id<b.id;}void MemoryReclaimer::up(std::size_t i){while(i){auto p=(i-1U)/2U;if(!better(heap_[i],heap_[p]))break;std::swap(heap_[i],heap_[p]);i=p;}}void MemoryReclaimer::down(std::size_t i){for(;;){auto b=i,l=2U*i+1U,r=l+1U;if(l<heap_.size()&&better(heap_[l],heap_[b]))b=l;if(r<heap_.size()&&better(heap_[r],heap_[b]))b=r;if(b==i)break;std::swap(heap_[i],heap_[b]);i=b;}}void MemoryReclaimer::push_snapshot(int id){const auto&r=records_.at(id);heap_.push_back({id,r.score,r.version});up(heap_.size()-1U);}bool MemoryReclaimer::track(int id,int score){if(id<=0||score<0||records_.count(id))return false;records_[id]={score,false,++version_};push_snapshot(id);return true;}bool MemoryReclaimer::rescore(int id,int score){auto it=records_.find(id);if(it==records_.end()||score<0)return false;it->second.score=score;it->second.version=++version_;if(!it->second.pinned)push_snapshot(id);return true;}bool MemoryReclaimer::set_pinned(int id,bool pinned){auto it=records_.find(id);if(it==records_.end()||it->second.pinned==pinned)return false;it->second.pinned=pinned;it->second.version=++version_;if(!pinned)push_snapshot(id);return true;}void MemoryReclaimer::purge(){while(!heap_.empty()){const auto s=heap_[0];auto it=records_.find(s.id);if(it!=records_.end()&&!it->second.pinned&&it->second.version==s.version)return;heap_[0]=heap_.back();heap_.pop_back();if(!heap_.empty())down(0);}}std::optional<MemoryReclaimer::Block> MemoryReclaimer::reclaim_next(){purge();if(heap_.empty())return std::nullopt;auto s=heap_[0];auto r=records_.at(s.id);records_.erase(s.id);heap_[0]=heap_.back();heap_.pop_back();if(!heap_.empty())down(0);purge();return Block{s.id,r.score,false};}bool MemoryReclaimer::debug_valid_heap()const{for(std::size_t i=1;i<heap_.size();++i)if(better(heap_[i],heap_[(i-1U)/2U]))return false;return true;}''',"lazy-versioned-heap")
    s=_source('''bool MemoryReclaimer::better(const Snapshot&,const Snapshot&){return false;}void MemoryReclaimer::up(std::size_t){}void MemoryReclaimer::down(std::size_t){}void MemoryReclaimer::push_snapshot(int){}bool MemoryReclaimer::track(int,int){return false;}bool MemoryReclaimer::rescore(int,int){return false;}bool MemoryReclaimer::set_pinned(int,bool){return false;}void MemoryReclaimer::purge(){}std::optional<MemoryReclaimer::Block> MemoryReclaimer::reclaim_next(){return std::nullopt;}bool MemoryReclaimer::debug_valid_heap()const{return false;}''',"lazy-versioned-heap")
    v=_test('''MemoryReclaimer q;check(q.track(1,5));check(q.track(2,9));check(q.set_pinned(2,true));check(q.rescore(1,12));check(q.reclaim_next()->id==1);check(q.set_pinned(2,false));check(q.reclaim_next()->id==2);''')
    x=_test('''MemoryReclaimer q;for(int i=1;i<=100;++i)check(q.track(i,i%23));for(int i=1;i<=100;++i){check(q.rescore(i,(i*11)%41));if(i%4==0)check(q.set_pinned(i,true));}int count=0;while(q.reclaim_next()){++count;check(q.debug_valid_heap());}check(count==75);check(q.pending()==25U);''')
    return Case("pq-memory-reclaimer","MemoryReclaimer","lazy-versioned-heap","Versioned snapshots lazily discard stale or pinned blocks.",h,r,s,v,x,("version","purge","push_snapshot"))


def _tournament() -> Case:
    h=_header('''class ConferenceTalks{public:struct Talk{int id;int readiness;int deadline;std::size_t room;};explicit ConferenceTalks(std::size_t rooms);bool set_room_candidate(std::size_t room,int id,int readiness,int deadline);bool clear_room(std::size_t room);std::optional<Talk> prepare_next();std::optional<std::size_t>winner_room()const;bool debug_valid_heap()const;private:std::size_t rooms_,base_=1;std::vector<std::optional<Talk>>leaves_;std::vector<int>winners_;static bool better(const std::optional<Talk>&,const std::optional<Talk>&);void update(std::size_t);int choose(int,int)const;};''')
    r=_source('''bool ConferenceTalks::better(const std::optional<Talk>&a,const std::optional<Talk>&b){if(!a)return false;if(!b)return true;return a->readiness!=b->readiness?a->readiness>b->readiness:a->deadline!=b->deadline?a->deadline<b->deadline:a->room<b->room;}ConferenceTalks::ConferenceTalks(std::size_t rooms):rooms_(rooms){if(!rooms)throw std::invalid_argument("rooms");while(base_<rooms_)base_*=2U;leaves_.resize(base_);winners_.assign(base_*2U,-1);for(std::size_t i=0;i<base_;++i)winners_[base_+i]=static_cast<int>(i);for(std::size_t i=base_;i-- >1U;)winners_[i]=choose(winners_[2U*i],winners_[2U*i+1U]);}int ConferenceTalks::choose(int a,int b)const{if(a<0)return b;if(b<0)return a;return better(leaves_[static_cast<std::size_t>(a)],leaves_[static_cast<std::size_t>(b)])?a:b;}void ConferenceTalks::update(std::size_t room){auto i=(base_+room)/2U;while(i){winners_[i]=choose(winners_[2U*i],winners_[2U*i+1U]);i/=2U;}}bool ConferenceTalks::set_room_candidate(std::size_t room,int id,int readiness,int deadline){if(room>=rooms_||id<=0||readiness<0||deadline<0)return false;leaves_[room]=Talk{id,readiness,deadline,room};update(room);return true;}bool ConferenceTalks::clear_room(std::size_t room){if(room>=rooms_||!leaves_[room])return false;leaves_[room].reset();update(room);return true;}std::optional<std::size_t> ConferenceTalks::winner_room()const{if(winners_[1]<0||!leaves_[static_cast<std::size_t>(winners_[1])])return std::nullopt;return static_cast<std::size_t>(winners_[1]);}std::optional<ConferenceTalks::Talk> ConferenceTalks::prepare_next(){auto room=winner_room();if(!room)return std::nullopt;auto out=leaves_[*room];clear_room(*room);return out;}bool ConferenceTalks::debug_valid_heap()const{for(std::size_t i=1;i<base_;++i)if(winners_[i]!=choose(winners_[2U*i],winners_[2U*i+1U]))return false;return true;}''',"winner-tournament-tree")
    s=_source('''bool ConferenceTalks::better(const std::optional<Talk>&,const std::optional<Talk>&){return false;}ConferenceTalks::ConferenceTalks(std::size_t rooms):rooms_(rooms){}int ConferenceTalks::choose(int,int)const{return -1;}void ConferenceTalks::update(std::size_t){}bool ConferenceTalks::set_room_candidate(std::size_t,int,int,int){return false;}bool ConferenceTalks::clear_room(std::size_t){return false;}std::optional<std::size_t> ConferenceTalks::winner_room()const{return std::nullopt;}std::optional<ConferenceTalks::Talk> ConferenceTalks::prepare_next(){return std::nullopt;}bool ConferenceTalks::debug_valid_heap()const{return false;}''',"winner-tournament-tree")
    v=_test('''ConferenceTalks q(3);check(q.set_room_candidate(0,1,4,20));check(q.set_room_candidate(1,2,8,40));check(q.set_room_candidate(2,3,8,10));check(q.winner_room()==2U);check(q.prepare_next()->id==3);check(q.prepare_next()->id==2);''')
    x=_test('''ConferenceTalks q(17);for(std::size_t i=0;i<17;++i)check(q.set_room_candidate(i,static_cast<int>(i+1),static_cast<int>((i*13)%19),100-static_cast<int>(i)));for(int i=0;i<17;++i){check(q.prepare_next().has_value());check(q.debug_valid_heap());}check(!q.prepare_next());''')
    return Case("pq-conference-talks","ConferenceTalks","winner-tournament-tree","A fixed-leaf tournament updates only the changed room path.",h,r,s,v,x,("winners_","choose(","base_*2U"))


