    return {
        "indexed-binary-max-heap": _oracle_emergency,
        "four-ary-ready-heap": _oracle_build,
        "tiered-fifo-buckets": _oracle_flight,
        "weighted-two-lane-cycle": _oracle_print,
        "aging-acuity-buckets": _oracle_hospital,
        "monotone-radix-heap": _oracle_network,
        "heap-of-zone-heads": _oracle_warehouse,
        "pairing-heap-meld": _oracle_snow,
        "leftist-heap-meld": _oracle_support,
        "price-level-book": _oracle_auction,
        "srpt-preemptive-heap": _oracle_video,
        "circular-calendar-queue": _oracle_calendar,
        "min-max-heap": _oracle_minmax,
        "adjacent-gap-candidate-heap": _oracle_matchmaking,
        "lazy-versioned-heap": _oracle_memory,
        "winner-tournament-tree": _oracle_tournament,
        "binomial-heap-union": _oracle_security,
        "skill-partitioned-indexed-heaps": _oracle_maintenance,
        "bounded-top-k-min-heap": _oracle_topk,
        "weighted-fair-head-heap": _oracle_fair,
    }.get(case.mechanism, lambda: case.hidden)()


